require __DIR__.'/bootstrap.php';require_auth();if(!can('sales.create')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='create_customer'){
 verify_csrf();$db->beginTransaction();try{$name=trim($_POST['customer_name']);if($name==='')throw new RuntimeException('Enter the customer name.');$next=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM customers')->fetchColumn();$code=trim($_POST['customer_code'])?:'CUS-'.str_pad((string)$next,5,'0',STR_PAD_LEFT);$credit=isset($_POST['credit_enabled'])?1:0;$opening=max(0,(float)($_POST['opening_balance']??0));if($opening>0)$credit=1;$db->prepare('INSERT INTO customers(customer_code,name,phone,customer_type,credit_enabled,default_payment_period,outstanding) VALUES(?,?,?,?,?,?,?)')->execute([$code,$name,trim($_POST['phone']),$_POST['customer_type'],$credit,$_POST['default_payment_period'],$opening]);$id=(int)$db->lastInsertId();if($opening>0)$db->prepare('INSERT INTO customer_opening_balances(customer_id,opening_date,amount,notes,created_by) VALUES(?,CURDATE(),?,?,?)')->execute([$id,$opening,'Opening balance entered when account was created',user()['id']]);audit($db,'create','customer',$id,null,['name'=>$name,'credit_enabled'=>$credit,'opening_balance'=>$opening]);$db->commit();flash('success','Customer account created and selected.');redirect('sale.php?mode='.urlencode($_POST['sale_mode']??'cash').'&customer='.$id);}catch(Throwable $e){$db->rollBack();flash('danger',$e->getMessage());redirect('sale.php');}
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$db->beginTransaction();try{$saleType=$_POST['sale_type']==='wholesale'?'wholesale':'retail';$paymentType=$_POST['payment_type']==='credit'?'credit':'cash';$customerId=(int)($_POST['customer_id']??0)?:null;if($paymentType==='credit'){if(!$customerId)throw new RuntimeException('Choose or create a credit customer.');$s=$db->prepare('SELECT credit_enabled FROM customers WHERE id=?');$s->execute([$customerId]);if(!(int)$s->fetchColumn())throw new RuntimeException('Credit is not enabled for this customer.');}$warranty=max(0,(int)($_POST['warranty_months']??0));$lines=[];$subtotal=0;foreach($_POST['product_id']??[] as $i=>$pid){$qty=(float)($_POST['quantity'][$i]??0);if(!$pid||$qty<=0)continue;$s=$db->prepare('SELECT * FROM products WHERE id=? AND status="active" FOR UPDATE');$s->execute([(int)$pid]);$p=$s->fetch();if(!$p)throw new RuntimeException('Product not found.');if($qty>(float)$p['current_stock'])throw new RuntimeException($p['name'].' only has '.$p['current_stock'].' available.');$price=(float)$p[$saleType.'_price'];$discount=max(0,(float)($_POST['line_discount'][$i]??0));$lines[]=[$p,$qty,$price,$discount];$subtotal+=$qty*$price-$discount;}if(!$lines)throw new RuntimeException('Search and add at least one product.');$invoiceDiscount=max(0,(float)($_POST['discount']??0));$total=max(0,$subtotal-$invoiceDiscount);$paid=max(0,min($total,(float)($_POST['paid_amount']??0)));if($paymentType==='cash'&&$paid<$total)throw new RuntimeException('For Pay Now, enter the full amount received.');$balance=$total-$paid;$status=$balance<=0?'paid':($paid>0?'partially_paid':'unpaid');$seq=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM sales')->fetchColumn();$saleNo='SALE-'.date('Y').'-'.str_pad((string)$seq,6,'0',STR_PAD_LEFT);$db->prepare('INSERT INTO sales(sale_no,customer_id,sale_date,sale_type,payment_type,subtotal,discount,total,paid_amount,balance,due_date,status,notes,created_by) VALUES(?,?,NOW(),?,?,?,?,?,?,?,?,?,?,?)')->execute([$saleNo,$customerId,$saleType,$paymentType,$subtotal,$invoiceDiscount,$total,$paid,$balance,$_POST['due_date']?:null,$status,trim($_POST['notes']??''),user()['id']]);$saleId=(int)$db->lastInsertId();$item=$db->prepare('INSERT INTO sale_items(sale_id,product_id,quantity,unit_price,historical_unit_cost,discount,warranty_months,line_total,gross_profit) VALUES(?,?,?,?,?,?,?,?,?)');$stock=$db->prepare('UPDATE products SET current_stock=current_stock-? WHERE id=?');$move=$db->prepare('INSERT INTO stock_movements(product_id,movement_type,quantity,unit_cost,running_quantity,reference_type,reference_id,created_by) VALUES(?,?,?,?,?,?,?,?)');foreach($lines as [$p,$qty,$price,$discount]){$before=$qty*$price-$discount;$allocated=$subtotal>0?$invoiceDiscount*($before/$subtotal):0;$lineTotal=$before-$allocated;$profit=$lineTotal-$qty*(float)$p['avg_cost'];$item->execute([$saleId,$p['id'],$qty,$price,$p['avg_cost'],$discount+$allocated,$warranty,$lineTotal,$profit]);$stock->execute([$qty,$p['id']]);$move->execute([$p['id'],$paymentType.'_sale',-$qty,$p['avg_cost'],(float)$p['current_stock']-$qty,'sale',$saleId,user()['id']]);}if($paid>0)$db->prepare('INSERT INTO sale_payments(sale_id,method,amount,reference_no) VALUES(?,?,?,?)')->execute([$saleId,$_POST['payment_method'],$paid,trim($_POST['reference_no']??'')]);if($customerId)$db->prepare('UPDATE customers SET outstanding=outstanding+?,total_sales=total_sales+?,total_payments=total_payments+?,last_purchase_at=NOW() WHERE id=?')->execute([$balance,$total,$paid,$customerId]);audit($db,'create','sale',$saleId,null,['sale_no'=>$saleNo,'total'=>$total]);$db->commit();flash('success',"Sale $saleNo saved.");redirect('sale.php');}catch(Throwable $e){$db->rollBack();flash('danger',$e->getMessage());redirect('sale.php');}
}
$products=$db->query('SELECT id,item_code,name,barcode,current_stock,retail_price,wholesale_price FROM products WHERE status="active" AND current_stock>0 ORDER BY name')->fetchAll();$customers=$db->query('SELECT id,customer_code,name,phone,customer_type,credit_enabled,outstanding FROM customers WHERE status="active" ORDER BY name')->fetchAll();$selected=(int)($_GET['customer']??0);$mode=in_array($_GET['mode']??'',['cash','credit'],true)?$_GET['mode']:'';page_start($mode==='cash'?'Cash Sale':($mode==='credit'?'Credit Sale':'New Sale'),'sale.php');if($mode===''){?>
<style>.sale-choice-wrap{max-width:980px;margin:45px auto}.sale-choice-title{text-align:center;margin-bottom:28px}.sale-choice-title h2{font-size:34px;margin:8px 0}.sale-choice-title p{color:#718078;font-size:16px}.sale-choices{display:grid;grid-template-columns:1fr 1fr;gap:22px}.sale-choice{background:#fff;border:2px solid #e0e7e1;border-radius:20px;padding:34px;min-height:280px;display:flex;flex-direction:column;transition:.2s}.sale-choice:hover{transform:translateY(-4px);border-color:#174e39;box-shadow:0 18px 45px rgba(23,78,57,.12)}.sale-choice .choice-icon{width:66px;height:66px;border-radius:18px;background:#e7f2df;color:#174e39;display:grid;place-items:center;font-size:28px;font-weight:800}.sale-choice.credit .choice-icon{background:#fff0d9;color:#a66c14}.sale-choice h3{font-size:25px;margin:22px 0 7px}.sale-choice p{color:#718078;line-height:1.6}.sale-choice ul{padding-left:20px;color:#526158;line-height:1.8}.sale-choice b{margin-top:auto;color:#174e39;font-size:16px}@media(max-width:700px){.sale-choices{grid-template-columns:1fr}}</style><section class="sale-choice-wrap"><div class="sale-choice-title"><span class="eyebrow">Choose before you start</span><h2>What type of sale is this?</h2><p>This choice cannot change while entering the invoice.</p></div><div class="sale-choices"><a class="sale-choice" href="sale.php?mode=cash"><span class="choice-icon">Rs</span><h3>Cash Sale</h3><p>The full invoice is paid now.</p><ul><li>Walk-in or account customer</li><li>Cash, card, bank, cheque or mixed</li><li>No outstanding balance</li></ul><b>Start Cash Sale →</b></a><a class="sale-choice credit" href="sale.php?mode=credit"><span class="choice-icon">30</span><h3>Credit Sale</h3><p>All or part of the invoice will be paid later.</p><ul><li>Customer account required</li><li>Zero payment or part payment allowed</li><li>Due date and outstanding balance saved</li></ul><b>Start Credit Sale →</b></a></div></section><?php page_end();exit;}?>
<style>.wizard-steps span{position:relative}.wizard-steps span:not(:last-child)::after{content:'→';position:absolute;right:-13px;top:50%;transform:translateY(-50%);z-index:2;width:26px;height:26px;display:grid;place-items:center;border-radius:50%;background:#cbe85b;color:#174e39;font-weight:900}.mode-display{padding:12px 14px;border:2px solid #174e39;border-radius:9px;background:#edf4e9;color:#174e39;font-weight:800}.customer-choice{display:grid;grid-template-columns:1fr auto;gap:10px}.quick-customer{margin-top:14px;border:1px solid #dfe6df;border-radius:10px;background:#f8faf7}.quick-customer summary{padding:13px 15px;cursor:pointer;font-weight:700;color:#174e39}.quick-customer form{padding:0 15px 15px}.product-finder{display:grid;grid-template-columns:1fr auto;gap:10px;padding:0 20px 18px}.product-finder input{font-size:16px}.sale-lines select.product{min-width:260px}.payment-extra.hidden{display:none}</style><div class="wizard-steps"><span class="active">1 Customer</span><span>2 Add Products</span><span>3 Payment</span><span>4 Save</span></div><form method="post" id="sale-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><div class="sale-layout"><section><article class="panel"><div class="panel-head"><div><span class="eyebrow">Step 1</span><h3>Find the customer</h3></div></div><label>Search by name, phone or customer code<input id="customer-search" placeholder="Start typing..."></label><label style="margin-top:10px">Selected customer<select name="customer_id" id="customer-select"><option value="">Walk-in customer / no account</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" data-search="<?=e(strtolower($c['customer_code'].' '.$c['name'].' '.$c['phone']))?>" data-credit="<?=$c['credit_enabled']?>" <?=$selected===$c['id']?'selected':''?>><?=e($c['name'].' - '.$c['phone'].($c['credit_enabled']?' (Credit, owes '.money($c['outstanding']).')':''))?></option><?php endforeach;?></select></label><details class="quick-customer"><summary>Customer not found? Create account here</summary><div style="padding:0 15px 15px"><div class="form-grid"><label>Customer name<input name="new_customer_name" data-new></label><label>Phone<input name="new_phone" data-new></label></div><button type="button" class="btn secondary" id="open-customer">Open quick account form</button></div></details><div class="form-grid" style="margin-top:14px"><label>Selling price<select name="sale_type" id="sale-type"><option value="retail">Retail</option><option value="wholesale">Wholesale</option></select></label><input type="hidden" name="payment_type" id="payment-type" value="<?=e($mode)?>"><label>Sale type<div class="mode-display"><?=$mode==='cash'?'Cash Sale - paid fully now':'Credit Sale - pay later / part payment'?></div></label><label class="payment-extra <?=$mode==='credit'?'':'hidden'?>">Credit due date<input type="date" name="due_date"></label></div></article><article class="panel table-panel sale-lines" style="margin-top:20px"><div class="panel-head"><div><span class="eyebrow">Step 2</span><h3>Search and add products</h3></div></div><div class="product-finder"><input id="product-search" list="product-list" placeholder="Type product name, code or barcode"><datalist id="product-list"><?php foreach($products as $p):?><option value="<?=e($p['item_code'].' - '.$p['name'])?>"></option><?php endforeach;?></datalist><button type="button" class="btn primary" id="find-product">+ Add</button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Stock</th><th>Qty</th><th>Discount</th><th class="right">Amount</th><th></th></tr></thead><tbody id="lines"></tbody></table></div></article></section><aside class="panel sale-summary"><div class="panel-head"><div><span class="eyebrow">Step 3</span><h3>Payment</h3></div></div><div class="summary-row"><span>Products</span><b id="subtotal">Rs. 0.00</b></div><label>Discount<input type="number" name="discount" id="discount" value="0" min="0" step=".01"></label><div class="summary-row total"><span>Total</span><strong id="total">Rs. 0.00</strong></div><label>Received now<input type="number" name="paid_amount" id="paid" value="0" min="0" step=".01"></label><div class="summary-row"><span>Still due</span><b id="balance">Rs. 0.00</b></div><label>Method<select name="payment_method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank</option><option value="cheque">Cheque</option><option value="other">Mixed</option></select></label><label>Warranty<select name="warranty_months"><option value="0">No warranty</option><option value="3">3 months</option><option value="6">6 months</option><option value="12">1 year</option><option value="24">2 years</option><option value="36">3 years</option></select></label><label>Notes<textarea name="notes" rows="2"></textarea></label><button class="btn primary wide" style="margin-top:12px">Save Sale</button></aside></div></form>
<form method="post" id="customer-modal" class="panel" style="display:none;position:fixed;z-index:50;inset:10% 30%;overflow:auto"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create_customer"><input type="hidden" name="sale_mode" value="<?=e($mode)?>"><div class="panel-head"><div><span class="eyebrow">Quick account</span><h3>Create Customer</h3></div><button type="button" class="icon-button" id="close-customer">×</button></div><div class="form-grid"><label class="full">Customer name<input name="customer_name" required></label><label>Phone<input name="phone"></label><label>Customer code (optional)<input name="customer_code"></label><label>Customer type<select name="customer_type"><option value="retail">Retail</option><option value="wholesale">Wholesale</option><option value="both">Both</option></select></label><label>Default payment period<select name="default_payment_period"><option value="7_days">7 days</option><option value="14_days">14 days</option><option value="30_days" selected>30 days</option><option value="end_of_month">End of month</option></select></label><label class="full"><span><input type="checkbox" name="credit_enabled"> Allow credit purchases</span></label><label class="full">Existing amount customer already owes<input type="number" name="opening_balance" min="0" step=".01" value="0"><small>Keep zero for a new credit account without old debt.</small></label><button class="btn primary full">Create & Select Customer</button></div></form>
<template id="line-template"><tr><td><select name="product_id[]" class="product" required><option value="">Choose</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" data-stock="<?=$p['current_stock']?>" data-retail="<?=$p['retail_price']?>" data-wholesale="<?=$p['wholesale_price']?>" data-search="<?=e(strtolower($p['item_code'].' '.$p['name'].' '.$p['barcode']))?>"><?=e($p['item_code'].' - '.$p['name'])?></option><?php endforeach;?></select></td><td class="stock">—</td><td><input class="qty" type="number" name="quantity[]" min=".001" step=".001" value="1"></td><td><input class="disc" type="number" name="line_discount[]" min="0" step=".01" value="0"></td><td class="right amount">Rs. 0.00</td><td><button type="button" class="icon-button remove">×</button></td></tr></template>
<script>const lines=document.querySelector('#lines'),tpl=document.querySelector('#line-template'),fmt=n=>'Rs. '+n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function calc(){let sub=0;lines.querySelectorAll('tr').forEach(r=>{let o=r.querySelector('.product').selectedOptions[0],p=+(o?.dataset[document.querySelector('#sale-type').value]||0),a=Math.max(0,p*(+r.querySelector('.qty').value||0)-(+r.querySelector('.disc').value||0));r.querySelector('.stock').textContent=o?.dataset.stock||'—';r.querySelector('.amount').textContent=fmt(a);sub+=a});let t=Math.max(0,sub-(+discount.value||0));subtotal.textContent=fmt(sub);total.textContent=fmt(t);balance.textContent=fmt(Math.max(0,t-(+paid.value||0)))}function addProduct(query=''){let node=tpl.content.cloneNode(true),sel=node.querySelector('.product');if(query){let match=[...sel.options].find(o=>o.dataset.search?.includes(query.toLowerCase())||o.text.toLowerCase()===query.toLowerCase());if(!match){alert('Product not found. Try another name or code.');return}sel.value=match.value}lines.append(node);calc()}document.querySelector('#find-product').onclick=()=>{addProduct(document.querySelector('#product-search').value);document.querySelector('#product-search').value=''};document.querySelector('#product-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();document.querySelector('#find-product').click()}});lines.addEventListener('input',calc);lines.addEventListener('change',calc);lines.addEventListener('click',e=>{if(e.target.classList.contains('remove')){e.target.closest('tr').remove();calc()}});discount.oninput=paid.oninput=document.querySelector('#sale-type').onchange=calc;document.querySelector('#customer-search').oninput=e=>{let q=e.target.value.toLowerCase(),sel=document.querySelector('#customer-select'),match=[...sel.options].find(o=>o.dataset.search?.includes(q));if(match)sel.value=match.value};document.querySelector('#payment-type').onchange=e=>document.querySelector('.payment-extra').classList.toggle('hidden',e.target.value!=='credit');document.querySelector('#open-customer').onclick=()=>document.querySelector('#customer-modal').style.display='block';document.querySelector('#close-customer').onclick=()=>document.querySelector('#customer-modal').style.display='none';</script><?php page_end();
